{
  "name": "@postmill-ai/postmill-cli",
  "version": "0.1.0",
  "description": "Official command-line interface for the Postmill platform",
  "type": "module",
  "license": "AGPL-3.0",
  "packageManager": "pnpm@11.2.2",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/postmill-ai/postmill-cli.git"
  },
  "bin": {
    "postmill": "dist/cli.js"
  },
  "files": [
    "dist"
  ],
  "engines": {
    "node": ">=20"
  },
  "scripts": {
    "dev": "tsup --watch",
    "build": "tsup",
    "typecheck": "tsc --noEmit",
    "test": "vitest run"
  },
  "dependencies": {
    "commander": "^14.0.0"
  },
  "devDependencies": {
    "@types/node": "^22.10.0",
    "tsup": "^8.3.5",
    "typescript": "^5.7.2",
    "vitest": "^3.0.0"
  }
}

import { createInterface } from 'node:readline/promises';
import type { Command } from 'commander';
import { createClient } from '../client.js';
import {
  DEFAULT_BASE_URL,
  credentialsFileDisplay,
  deleteConfig,
  saveConfig,
} from '../config.js';
import { CliError, printResult } from '../output.js';
import { credentialsFor, globalOpts, requireClient, withErrors } from '../context.js';
import type { IsConnectedResponse } from '../types.js';

async function loginAction(): Promise<void> {
  if (!process.stdin.isTTY) {
    throw new CliError(
      '`postmill login` is interactive. In scripts, use --api-key or the POSTMILL_API_KEY env var instead.',
    );
  }

  const rl = createInterface({ input: process.stdin, output: process.stdout });
  let baseUrl: string;
  let apiKey: string;
  try {
    baseUrl = (await rl.question(`Base URL [${DEFAULT_BASE_URL}]: `)).trim() || DEFAULT_BASE_URL;
    apiKey = (await rl.question('API key (dashboard → Settings → API Keys): ')).trim();
  } finally {
    rl.close();
  }

  if (!apiKey) {
    throw new CliError('No API key entered — login aborted.');
  }

  const client = createClient({ apiKey, baseUrl });
  const res = await client.get<IsConnectedResponse>('/is-connected');
  if (!res.connected) {
    throw new CliError('The server did not accept this API key.');
  }

  saveConfig({ apiKey, baseUrl });
  printResult(
    { connected: true, baseUrl, configFile: credentialsFileDisplay() },
    {
      json: false,
      text: `Logged in. Credentials saved to ${credentialsFileDisplay()} (permissions 0600).`,
    },
  );
}

function statusAction(_opts: unknown, cmd: Command): Promise<void> {
  const opts = globalOpts(cmd);
  const creds = credentialsFor(cmd);
  if (!creds.apiKey) {
    throw new CliError(
      'You are not logged in. Run `postmill login`, set POSTMILL_API_KEY, or pass --api-key.',
    );
  }

  const client = requireClient(cmd);
  return client.get<IsConnectedResponse>('/is-connected').then((res) => {
    printResult(
      { connected: res.connected, baseUrl: creds.baseUrl, apiKeySource: creds.apiKeySource },
      {
        json: opts.json,
        text: res.connected
          ? `Connected to ${creds.baseUrl} (API key from ${creds.apiKeySource}).`
          : 'Not connected.',
      },
    );
  });
}

function logoutAction(_opts: unknown, cmd: Command): void {
  const opts = globalOpts(cmd);
  const removed = deleteConfig();
  printResult(
    { loggedOut: true, configFileRemoved: removed },
    {
      json: opts.json,
      text: removed
        ? `Logged out — removed ${credentialsFileDisplay()}. Env vars (POSTMILL_API_KEY) are untouched.`
        : 'No saved credentials found — nothing to remove. Env vars (POSTMILL_API_KEY) are untouched.',
    },
  );
}

export function registerAuthCommands(program: Command): void {
  program
    .command('login')
    .description('Interactively save an API key (and optional base URL) to the config file')
    .action(withErrors(loginAction));

  program
    .command('status')
    .description('Check whether the saved/provided API key is accepted by the server')
    .action(withErrors(statusAction));

  program
    .command('logout')
    .description('Remove the saved credentials file')
    .action(withErrors(logoutAction));
}

import { defineConfig } from 'vitest/config';

export default defineConfig({
  test: {
    include: ['test/**/*.test.ts'],
    environment: 'node',
  },
});

import { mkdtempSync, readFileSync, statSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';
import {
  DEFAULT_BASE_URL,
  deleteConfig,
  loadConfig,
  resolveCredentials,
  saveConfig,
} from '../src/config.js';

function tempConfigDir(): { dir: string; path: string } {
  const dir = mkdtempSync(join(tmpdir(), 'postmill-cli-test-'));
  return { dir, path: join(dir, 'config.json') };
}

describe('config file', () => {
  it('returns {} when the file is missing or invalid', () => {
    const { path } = tempConfigDir();
    expect(loadConfig(path)).toEqual({});
    writeFileSync(path, 'not json');
    expect(loadConfig(path)).toEqual({});
  });

  it('saves with mode 0600 and reloads', () => {
    const { path } = tempConfigDir();
    saveConfig({ apiKey: 'pm_live_x', baseUrl: 'https://self.hosted' }, path);

    expect(statSync(path).mode & 0o777).toBe(0o600);
    expect(loadConfig(path)).toEqual({ apiKey: 'pm_live_x', baseUrl: 'https://self.hosted' });

    // re-save keeps 0600 even though the file already exists
    saveConfig({ apiKey: 'pm_live_y' }, path);
    expect(statSync(path).mode & 0o777).toBe(0o600);
  });

  it('deleteConfig removes the file and reports whether it existed', () => {
    const { path } = tempConfigDir();
    expect(deleteConfig(path)).toBe(false);
    saveConfig({ apiKey: 'k' }, path);
    expect(deleteConfig(path)).toBe(true);
    expect(loadConfig(path)).toEqual({});
  });
});

describe('credential precedence', () => {
  it('flag > env > config file; base URL defaults to hosted', () => {
    const { path } = tempConfigDir();
    writeFileSync(path, JSON.stringify({ apiKey: 'file-key', baseUrl: 'https://file.url' }));

    // file only
    expect(resolveCredentials({}, {}, path)).toEqual({
      apiKey: 'file-key',
      baseUrl: 'https://file.url',
      apiKeySource: 'config',
    });

    // env beats file
    expect(
      resolveCredentials({}, { POSTMILL_API_KEY: 'env-key', POSTMILL_BASE_URL: 'https://env.url' }, path),
    ).toEqual({ apiKey: 'env-key', baseUrl: 'https://env.url', apiKeySource: 'env' });

    // flag beats env
    expect(
      resolveCredentials(
        { apiKey: 'flag-key', baseUrl: 'https://flag.url' },
        { POSTMILL_API_KEY: 'env-key', POSTMILL_BASE_URL: 'https://env.url' },
        path,
      ),
    ).toEqual({ apiKey: 'flag-key', baseUrl: 'https://flag.url', apiKeySource: 'flag' });
  });

  it('falls back to the hosted default base URL', () => {
    const { path } = tempConfigDir();
    const res = resolveCredentials({}, {}, path);
    expect(res.baseUrl).toBe(DEFAULT_BASE_URL);
    expect(res.apiKey).toBeUndefined();
    expect(res.apiKeySource).toBeUndefined();
  });

  it('keeps file contents readable on disk as plain JSON', () => {
    const { path } = tempConfigDir();
    saveConfig({ apiKey: 'k' }, path);
    expect(JSON.parse(readFileSync(path, 'utf8'))).toEqual({ apiKey: 'k' });
  });
});

import { afterEach, describe, expect, it, vi } from 'vitest';
import { ApiError, createClient, paginatePosts } from '../src/client.js';

function jsonResponse(body: unknown, status = 200, headers: Record<string, string> = {}) {
  return new Response(JSON.stringify(body), {
    status,
    headers: { 'content-type': 'application/json', ...headers },
  });
}

function stubFetch(handler: (url: string, init: RequestInit) => Response | Promise<Response>) {
  const calls: { url: string; init: RequestInit }[] = [];
  vi.stubGlobal('fetch', async (url: string | URL, init?: RequestInit) => {
    const u = String(url);
    const i = init ?? {};
    calls.push({ url: u, init: i });
    return handler(u, i);
  });
  return calls;
}

afterEach(() => {
  vi.unstubAllGlobals();
});

const opts = { apiKey: '[REDACTED]', baseUrl: 'https://api.postmill.ai' };

/** Await a rejection and return it typed as ApiError. */
async function catchApiError(p: Promise<unknown>): Promise<ApiError> {
  try {
    await p;
  } catch (e) {
    return e as ApiError;
  }
  throw new Error('expected the request to fail');
}

describe('client', () => {
  it('sends the API key raw in Authorization (no Bearer) and prefixes /public/v1', async () => {
    const calls = stubFetch(() => jsonResponse({ connected: true }));
    const client = createClient(opts);

    await client.get('/is-connected');

    expect(calls).toHaveLength(1);
    expect(calls[0].url).toBe('https://api.postmill.ai/public/v1/is-connected');
    const headers = calls[0].init.headers as Record<string, string>;
    expect(headers.Authorization).toBe('pm_live_test');
    expect(headers.Authorization).not.toContain('Bearer');
  });

  it('adds an Idempotency-Key UUID on POST/PUT/DELETE but not GET', async () => {
    const calls = stubFetch(() => jsonResponse({}));
    const client = createClient(opts);

    await client.post('/posts', { body: { a: 1 } });
    await client.put('/posts/1/status', { body: { status: 'draft' } });
    await client.delete('/posts/1');
    await client.get('/posts');

    const headerOf = (i: number) =>
      (calls[i].init.headers as Record<string, string>)['Idempotency-Key'];
    const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;
    expect(headerOf(0)).toMatch(uuid);
    expect(headerOf(1)).toMatch(uuid);
    expect(headerOf(2)).toMatch(uuid);
    expect(headerOf(3)).toBeUndefined();
    // distinct per invocation
    expect(new Set([headerOf(0), headerOf(1), headerOf(2)]).size).toBe(3);
  });

  it('honors a caller-supplied Idempotency-Key', async () => {
    const calls = stubFetch(() => jsonResponse({}));
    const client = createClient(opts);

    await client.post('/posts', { body: {}, idempotencyKey: 'my-key' });

    expect((calls[0].init.headers as Record<string, string>)['Idempotency-Key']).toBe('my-key');
  });

  it('sends JSON bodies and query params; skips undefined query values', async () => {
    const calls = stubFetch(() => jsonResponse({ posts: [], cursor: null }));
    const client = createClient(opts);

    await client.get('/posts', {
      query: { startDate: 'a', endDate: 'b', limit: 100, cursor: undefined },
    });
    await client.post('/upload-from-url', { body: { url: 'https://x/img.png' } });

    const url = new URL(calls[0].url);
    expect(url.searchParams.get('startDate')).toBe('a');
    expect(url.searchParams.get('limit')).toBe('100');
    expect(url.searchParams.has('cursor')).toBe(false);

    const headers = calls[1].init.headers as Record<string, string>;
    expect(headers['Content-Type']).toBe('application/json');
    expect(JSON.parse(String(calls[1].init.body))).toEqual({ url: 'https://x/img.png' });
  });

  it('maps 401 to a friendly invalid-key error', async () => {
    stubFetch(() => jsonResponse({ msg: 'Invalid API key' }, 401));
    const client = createClient(opts);

    const err = await catchApiError(client.get('/posts'));
    expect(err).toBeInstanceOf(ApiError);
    expect(err.code).toBe('UNAUTHORIZED');
    expect(err.status).toBe(401);
    expect(err.message).toContain('Invalid API key');
    expect(err.message).toContain('postmill login');
  });

  it('maps 402 to BILLING, 410 to PROVIDER_RETIRED (with latestActive)', async () => {
    stubFetch((url) =>
      url.includes('social')
        ? jsonResponse({ providerId: 'x', version: 'v1', latestActive: 'v2' }, 410)
        : jsonResponse({ msg: 'quota' }, 402),
    );
    const client = createClient(opts);

    const billing = await catchApiError(client.post('/posts', { body: {} }));
    expect(billing.code).toBe('BILLING');
    expect(billing.message).toContain('plan');

    const retired = await catchApiError(client.get('/social/x', { query: { version: 'v1' } }));
    expect(retired.code).toBe('PROVIDER_RETIRED');
    expect(retired.message).toContain('retired');
    expect(retired.message).toContain('v2');
  });

  it('surfaces the server validation message on 400', async () => {
    stubFetch(() => jsonResponse({ msg: 'date must be a valid ISO date' }, 400));
    const client = createClient(opts);

    const err = await catchApiError(client.get('/posts'));
    expect(err.code).toBe('VALIDATION');
    expect(err.message).toContain('date must be a valid ISO date');
  });

  it('retries 429 once after Retry-After, then throws THROTTLED', async () => {
    const sleepCalls: number[] = [];
    const sleep = async (ms: number) => {
      sleepCalls.push(ms);
    };

    // Case 1: retry succeeds.
    let n = 0;
    const calls = stubFetch(() =>
      ++n === 1 ? jsonResponse({}, 429, { 'retry-after': '2' }) : jsonResponse({ ok: true }),
    );
    const client = createClient(opts, { sleep });

    const res = await client.get('/posts');
    expect(res).toEqual({ ok: true });
    expect(calls).toHaveLength(2);
    expect(sleepCalls).toEqual([2000]);

    // Case 2: still throttled after the single retry.
    vi.unstubAllGlobals();
    sleepCalls.length = 0;
    stubFetch(() => jsonResponse({}, 429, { 'retry-after': '1' }));
    const err = await catchApiError(createClient(opts, { sleep }).get('/posts'));
    expect(err).toBeInstanceOf(ApiError);
    expect(err.code).toBe('THROTTLED');
    expect(sleepCalls).toEqual([1000]);
  });

  it('does not retry other 4xx', async () => {
    const calls = stubFetch(() => jsonResponse({ msg: 'nope' }, 404));
    const client = createClient(opts, { sleep: async () => {} });

    await expect(client.get('/posts')).rejects.toMatchObject({ code: 'NOT_FOUND' });
    expect(calls).toHaveLength(1);
  });

  it('turns connection failures into a NETWORK ApiError', async () => {
    vi.stubGlobal('fetch', async () => {
      throw new TypeError('fetch failed');
    });
    const client = createClient(opts);

    const err = await catchApiError(client.get('/posts'));
    expect(err).toBeInstanceOf(ApiError);
    expect(err.code).toBe('NETWORK');
    expect(err.message).toContain('api.postmill.ai');
  });
});

describe('paginatePosts', () => {
  it('follows the cursor across pages until maxTotal', async () => {
    const makePosts = (from: number, count: number) =>
      Array.from({ length: count }, (_, i) => ({ id: `p${from + i}` }));
    const calls = stubFetch((url) => {
      const u = new URL(url);
      const cursor = Number(u.searchParams.get('cursor') ?? 0);
      const limit = Number(u.searchParams.get('limit'));
      const posts = makePosts(cursor, Math.min(limit, 250 - cursor));
      const next = cursor + limit;
      return jsonResponse({ posts, cursor: next < 250 ? next : null });
    });
    const client = createClient(opts);

    const { posts, cursor } = await paginatePosts(
      client,
      { startDate: 'a', endDate: 'b' },
      250,
    );

    expect(posts).toHaveLength(250);
    expect(calls).toHaveLength(3); // 100 + 100 + 50
    expect(calls[0].url).toContain('limit=100');
    expect(calls[1].url).toContain('cursor=100');
    expect(calls[2].url).toContain('limit=50');
    expect(cursor).toBeNull();
  });

  it('stops when the server returns no next cursor', async () => {
    const calls = stubFetch(() => jsonResponse({ posts: [{ id: 'p1' }], cursor: null }));
    const client = createClient(opts);

    const { posts } = await paginatePosts(client, { startDate: 'a', endDate: 'b' }, 100);

    expect(posts).toHaveLength(1);
    expect(calls).toHaveLength(1);
  });
});

import { mkdtempSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { createProgram } from '../src/cli.js';
import { pollVideoJob, buildGeneratePayload } from '../src/commands/video.js';
import { createClient } from '../src/client.js';

interface CapturedCall {
  url: string;
  method: string;
  headers: Record<string, string>;
  body?: string;
}

function jsonResponse(body: unknown, status = 200) {
  return new Response(JSON.stringify(body), {
    status,
    headers: { 'content-type': 'application/json' },
  });
}

let calls: CapturedCall[];
let stdout: string;
let stderr: string;
let home: string;
let realHome: string | undefined;

type Handler = (call: CapturedCall) => Response;

function stubFetchQueue(handlers: Handler[]) {
  let i = 0;
  vi.stubGlobal('fetch', async (url: string | URL, init?: RequestInit) => {
    const call: CapturedCall = {
      url: String(url),
      method: (init?.method ?? 'GET').toUpperCase(),
      headers: (init?.headers ?? {}) as Record<string, string>,
      body: init?.body === undefined ? undefined : String(init.body),
    };
    calls.push(call);
    const handler = handlers[Math.min(i, handlers.length - 1)];
    i += 1;
    return handler(call);
  });
}

async function run(args: string[]): Promise<number> {
  process.exitCode = 0;
  await createProgram().parseAsync(['node', 'postmill', '--api-key', 'test-key', ...args]);
  return process.exitCode ?? 0;
}

beforeEach(() => {
  calls = [];
  stdout = '';
  stderr = '';
  realHome = process.env.HOME;
  home = mkdtempSync(join(tmpdir(), 'postmill-cli-home-'));
  process.env.HOME = home; // keep ~/.config/postmill hermetic
  vi.spyOn(process.stdout, 'write').mockImplementation((chunk) => {
    stdout += String(chunk);
    return true;
  });
  vi.spyOn(process.stderr, 'write').mockImplementation((chunk) => {
    stderr += String(chunk);
    return true;
  });
});

afterEach(() => {
  vi.unstubAllGlobals();
  vi.restoreAllMocks();
  if (realHome === undefined) delete process.env.HOME;
  else process.env.HOME = realHome;
  process.exitCode = 0;
});

describe('posts commands', () => {
  it('posts list builds the correct query (dates + pagination limit)', async () => {
    stubFetchQueue([() => jsonResponse({ posts: [], cursor: null })]);

    const code = await run(['posts', 'list', '--from', '2026-01-01T00:00:00.000Z', '--to', '2026-01-31T23:59:59.000Z']);

    expect(code).toBe(0);
    const url = new URL(calls[0].url);
    expect(url.pathname).toBe('/public/v1/posts');
    expect(url.searchParams.get('startDate')).toBe('2026-01-01T00:00:00.000Z');
    expect(url.searchParams.get('endDate')).toBe('2026-01-31T23:59:59.000Z');
    expect(url.searchParams.get('limit')).toBe('100');
    expect(calls[0].method).toBe('GET');
  });

  it('posts create sends creationMethod CLI, type schedule, and one entry per channel', async () => {
    stubFetchQueue([() => jsonResponse({ group: 'g1' }, 201)]);

    const code = await run([
      'posts', 'create',
      '--channel', 'ch1',
      '--channel', 'ch2',
      '--content', 'hello world',
      '--date', '2026-02-01T12:00:00.000Z',
      '--media', 'https://cdn/x.png',
    ]);

    expect(code).toBe(0);
    expect(calls).toHaveLength(1);
    expect(calls[0].method).toBe('POST');
    expect(new URL(calls[0].url).pathname).toBe('/public/v1/posts');
    expect(calls[0].headers['Idempotency-Key']).toBeTruthy();
    const body = JSON.parse(calls[0].body!);
    expect(body.creationMethod).toBe('CLI');
    expect(body.type).toBe('schedule');
    expect(body.date).toBe('2026-02-01T12:00:00.000Z');
    expect(body.shortLink).toBe(false);
    expect(body.tags).toEqual([]);
    expect(body.posts).toHaveLength(2);
    expect(body.posts[0]).toEqual({
      integration: { id: 'ch1' },
      value: [{ content: 'hello world', image: [{ id: '', path: 'https://cdn/x.png' }] }],
      settings: {},
    });
    expect(body.posts[1].integration.id).toBe('ch2');
  });

  it('posts create --draft sends type draft', async () => {
    stubFetchQueue([() => jsonResponse({}, 201)]);
    await run(['posts', 'create', '--channel', 'ch1', '--content', 'x', '--date', '2026-02-01T00:00:00.000Z', '--draft']);
    expect(JSON.parse(calls[0].body!).type).toBe('draft');
  });

  it('posts create --slot resolves the date via GET /find-slot/:id first', async () => {
    stubFetchQueue([
      () => jsonResponse({ date: '2026-03-05T09:00:00.000Z' }),
      () => jsonResponse({ group: 'g9' }, 201),
    ]);

    const code = await run(['posts', 'create', '--channel', 'ch1', '--content', 'slot me', '--slot']);

    expect(code).toBe(0);
    expect(calls).toHaveLength(2);
    expect(new URL(calls[0].url).pathname).toBe('/public/v1/find-slot/ch1');
    expect(calls[0].method).toBe('GET');
    expect(new URL(calls[1].url).pathname).toBe('/public/v1/posts');
    expect(JSON.parse(calls[1].body!).date).toBe('2026-03-05T09:00:00.000Z');
  });

  it('posts create without --date/--slot fails with a friendly error and no request', async () => {
    stubFetchQueue([() => jsonResponse({})]);
    const code = await run(['posts', 'create', '--channel', 'ch1', '--content', 'x']);
    expect(code).toBe(1);
    expect(calls).toHaveLength(0);
    expect(stderr).toContain('--date');
  });

  it('posts delete / delete-group hit the right routes', async () => {
    stubFetchQueue([() => jsonResponse({}), () => jsonResponse({})]);
    await run(['posts', 'delete', 'p1']);
    await run(['posts', 'delete-group', 'g1']);
    expect(new URL(calls[0].url).pathname).toBe('/public/v1/posts/p1');
    expect(calls[0].method).toBe('DELETE');
    expect(new URL(calls[1].url).pathname).toBe('/public/v1/posts/group/g1');
  });

  it('posts status requires exactly one of --draft/--schedule and PUTs the status', async () => {
    stubFetchQueue([() => jsonResponse({})]);
    const bad = await run(['posts', 'status', 'p1']);
    expect(bad).toBe(1);
    expect(calls).toHaveLength(0);

    const good = await run(['posts', 'status', 'p1', '--draft']);
    expect(good).toBe(0);
    expect(new URL(calls[0].url).pathname).toBe('/public/v1/posts/p1/status');
    expect(calls[0].method).toBe('PUT');
    expect(JSON.parse(calls[0].body!)).toEqual({ status: 'draft' });
  });
});

describe('channels / media / notifications commands', () => {
  it('channels list GETs /integrations', async () => {
    stubFetchQueue([() => jsonResponse([{ id: 'i1', name: 'X acct', identifier: 'x', picture: null, disabled: false, profile: '@me' }])]);
    const code = await run(['channels', 'list']);
    expect(code).toBe(0);
    expect(new URL(calls[0].url).pathname).toBe('/public/v1/integrations');
  });

  it('channels connect passes ?version= to GET /social/:id', async () => {
    stubFetchQueue([() => jsonResponse({ url: 'https://oauth.example/authorize' })]);
    const code = await run(['channels', 'connect', 'x', '--provider-version', 'v1']);
    expect(code).toBe(0);
    const url = new URL(calls[0].url);
    expect(url.pathname).toBe('/public/v1/social/x');
    expect(url.searchParams.get('version')).toBe('v1');
  });

  it('media upload-url POSTs { url } to /upload-from-url', async () => {
    stubFetchQueue([() => jsonResponse({ id: 'f1', name: 'upload.png', path: 'https://cdn/upload.png' }, 201)]);
    const code = await run(['media', 'upload-url', 'https://example.com/pic.png']);
    expect(code).toBe(0);
    expect(new URL(calls[0].url).pathname).toBe('/public/v1/upload-from-url');
    expect(JSON.parse(calls[0].body!)).toEqual({ url: 'https://example.com/pic.png' });
  });

  it('notifications list passes a zero-based page', async () => {
    stubFetchQueue([() => jsonResponse({ notifications: [] })]);
    const code = await run(['notifications', 'list', '--page', '2']);
    expect(code).toBe(0);
    const url = new URL(calls[0].url);
    expect(url.pathname).toBe('/public/v1/notifications');
    expect(url.searchParams.get('page')).toBe('2');
  });
});

