import { Command } from 'commander';
import { registerAuthCommands } from './commands/auth.js';
import { registerPostsCommands } from './commands/posts.js';
import { registerChannelsCommands } from './commands/channels.js';
import { registerMediaCommands } from './commands/media.js';
import { registerVideoCommands } from './commands/video.js';
import { registerAnalyticsCommands } from './commands/analytics.js';
import { registerNotificationsCommands } from './commands/notifications.js';

// Keep in sync with package.json "version" (the publish workflow gates on the tag).
const VERSION = '0.1.0';

export function createProgram(): Command {
  const program = new Command();

  program
    .name('postmill')
    .description('Official CLI for the Postmill platform')
    .version(VERSION)
    .option('--json', 'Output JSON (automatic when stdout is not a TTY)')
    .option('--api-key <key>', 'API key (overrides POSTMILL_API_KEY and the config file)')
    .option('--base-url <url>', 'API base URL (overrides POSTMILL_BASE_URL and the config file)');

  registerAuthCommands(program);
  registerPostsCommands(program);
  registerChannelsCommands(program);
  registerMediaCommands(program);
  registerVideoCommands(program);
  registerAnalyticsCommands(program);
  registerNotificationsCommands(program);

  return program;
}

// Run only when executed directly (not when imported by tests).
const invokedAsScript = process.argv[1] && import.meta.url === new URL(`file://${process.argv[1]}`).href;
if (invokedAsScript) {
  createProgram().parseAsync(process.argv).catch((err: unknown) => {
    process.stderr.write(`Error: ${err instanceof Error ? err.message : String(err)}\n`);
    process.exitCode = 1;
  });
}

import { homedir } from 'node:os';
import { join } from 'node:path';
import { chmodSync, existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';

export const DEFAULT_BASE_URL = 'https://api.postmill.ai';

export interface StoredConfig {
  apiKey?: string;
  baseUrl?: string;
}

export interface CliFlags {
  apiKey?: string;
  baseUrl?: string;
}

export interface ResolvedCredentials {
  apiKey?: string;
  baseUrl: string;
  /** Where the api key came from, for display purposes. */
  apiKeySource?: 'flag' | 'env' | 'config';
}

export function defaultConfigPath(): string {
  return join(homedir(), '.config', 'postmill', 'config.json');
}

export function credentialsFileDisplay(): string {
  return defaultConfigPath();
}

export function loadConfig(path: string = defaultConfigPath()): StoredConfig {
  try {
    if (!existsSync(path)) return {};
    const parsed = JSON.parse(readFileSync(path, 'utf8'));
    return typeof parsed === 'object' && parsed !== null ? (parsed as StoredConfig) : {};
  } catch {
    return {};
  }
}

export function saveConfig(config: StoredConfig, path: string = defaultConfigPath()): void {
  mkdirSync(join(path, '..'), { recursive: true, mode: 0o700 });
  writeFileSync(path, JSON.stringify(config, null, 2) + '\n', { mode: 0o600 });
  // writeFileSync mode only applies on creation — enforce 0600 on re-login too.
  chmodSync(path, 0o600);
}

export function deleteConfig(path: string = defaultConfigPath()): boolean {
  if (!existsSync(path)) return false;
  rmSync(path);
  return true;
}

/**
 * Credential precedence (highest first):
 *   --api-key / --base-url flags  >  POSTMILL_API_KEY / POSTMILL_BASE_URL env  >  config file
 * Base URL falls back to DEFAULT_BASE_URL when nothing sets it.
 */
export function resolveCredentials(
  flags: CliFlags,
  env: NodeJS.ProcessEnv = process.env,
  configPath: string = defaultConfigPath(),
): ResolvedCredentials {
  const file = loadConfig(configPath);

  const apiKey = [REDACTED] ?? env.POSTMILL_API_KEY ?? file.apiKey;
  const apiKeySource = flags.apiKey
    ? 'flag'
    : env.POSTMILL_API_KEY
      ? 'env'
      : file.apiKey
        ? 'config'
        : undefined;

  const baseUrl = flags.baseUrl ?? env.POSTMILL_BASE_URL ?? file.baseUrl ?? DEFAULT_BASE_URL;

  return { apiKey, baseUrl, apiKeySource };
}

import type { Command } from 'commander';
import { createClient, type Client } from './client.js';
import { resolveCredentials, type ResolvedCredentials } from './config.js';
import { CliError, NOT_LOGGED_IN_MESSAGE, printError } from './output.js';

export interface GlobalOpts {
  json?: boolean;
  apiKey?: string;
  baseUrl?: string;
}

/** Merged local + global options for the command whose action is running. */
export function globalOpts(cmd: Command): GlobalOpts {
  return cmd.optsWithGlobals() as GlobalOpts;
}

export function credentialsFor(cmd: Command): ResolvedCredentials {
  const opts = globalOpts(cmd);
  return resolveCredentials({ apiKey: opts.apiKey, baseUrl: opts.baseUrl });
}

/** Client for the current command; fails with a friendly error when logged out. */
export function requireClient(cmd: Command): Client {
  const creds = credentialsFor(cmd);
  if (!creds.apiKey) {
    throw new CliError(NOT_LOGGED_IN_MESSAGE);
  }
  return createClient({ apiKey: [REDACTED], baseUrl: creds.baseUrl });
}

type Action<Args extends unknown[] = unknown[]> = (...args: Args) => void | Promise<void>;

/** Wrap a commander action: errors → friendly stderr message + exit code 1. */
export function withErrors<Args extends unknown[]>(fn: Action<Args>): Action<Args> {
  return (async (...args: Args) => {
    try {
      await fn(...args);
    } catch (err) {
      printError(err);
      process.exitCode = 1;
    }
  }) as Action<Args>;
}

/**
 * DTO mirrors for the Postmill Public REST API (`/public/v1/*`).
 * Shapes verified against postmill-app:
 *  - apps/backend/src/public-api/routes/v1/public.integrations.controller.ts
 *  - apps/backend/src/public-api/routes/v1/public.analytics.v1.controller.ts
 *  - libraries/nestjs-libraries/src/dtos/... and the generated openapi.yml
 */

// ── Channels (GET /integrations) ─────────────────────────────────────────────

export interface Integration {
  id: string;
  name: string;
  identifier: string;
  picture: string | null;
  disabled: boolean;
  profile: string | null;
}

// ── Media upload (POST /upload, POST /upload-from-url) ───────────────────────

export interface MediaItem {
  id: string;
  path: string;
  alt?: string;
  thumbnail?: string;
}

/** Saved file record returned by both upload routes (FileService.saveFile). */
export interface UploadedFile {
  id: string;
  name: string;
  path: string;
  [key: string]: unknown;
}

// ── Posts ────────────────────────────────────────────────────────────────────

export interface PostRecord {
  id: string;
  state: string;
  publishDate: string;
  content: string;
  group: string;
  integration?: { id: string; name: string; providerIdentifier?: string };
  [key: string]: unknown;
}

export interface PostsPage {
  posts: PostRecord[];
  cursor: number | null;
}

/** CreatePostDto (POST /posts). */
export interface CreatePostPayload {
  type: 'draft' | 'schedule' | 'now' | 'update';
  date: string;
  shortLink: boolean;
  tags: { value: string; label: string }[];
  creationMethod: 'CLI';
  posts: {
    integration: { id: string };
    value: { content: string; image: MediaItem[] }[];
    settings: Record<string, unknown>;
  }[];
}

/** GET /find-slot/:id */
export interface FindSlotResponse {
  date: string;
}

/** ChangePostStatusDto (PUT /posts/:id/status). */
export type PostStatus = 'draft' | 'schedule';

// ── Video (POST /generate-video, GET /generate-video/:id) ────────────────────

/** VideoDto (POST /generate-video). */
export interface GenerateVideoPayload {
  type: string;
  output: 'vertical' | 'horizontal';
  customParams?: Record<string, unknown>;
}

/** Public job contract shared by POST /generate-video and GET /generate-video/:id. */
export interface VideoJob {
  id: string | null;
  status: 'pending' | 'completed' | 'failed';
  artifactUrl: string | null;
  provider: string | null;
  error: string | null;
}

/** VideoFunctionDto (POST /video/function) — only `loadVoices` is supported. */
export interface VideoFunctionPayload {
  identifier: string;
  functionName: 'loadVoices';
  params?: Record<string, unknown>;
}

export interface Voice {
  id: string;
  name: string;
  preview_url: string;
}

// ── Misc ─────────────────────────────────────────────────────────────────────

export interface IsConnectedResponse {
  connected: boolean;
}

export interface ConnectUrlResponse {
  url: string;
}

export interface Notification {
  id: string;
  category?: string;
  message?: string;
  createdAt?: string;
  [key: string]: unknown;
}

import { ApiError } from './client.js';

/** Friendly, non-API CLI error (bad args, not logged in, ...) — no stack trace. */
export class CliError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'CliError';
  }
}

export const NOT_LOGGED_IN_MESSAGE =
  'You are not logged in. Run `postmill login`, set POSTMILL_API_KEY, or pass --api-key.';

export interface Column {
  /** Key into each row object. */
  key: string;
  /** Header label (defaults to the key). */
  label?: string;
  /** Max rendered width before truncation. */
  maxWidth?: number;
}

export interface TableData {
  columns: Column[];
  rows: Record<string, unknown>[];
}

function cellText(value: unknown): string {
  if (value === null || value === undefined) return '';
  if (typeof value === 'object') return JSON.stringify(value);
  return String(value);
}

/** Hand-rolled aligned table — no table dependency. */
export function formatTable(table: TableData): string {
  const headers = table.columns.map((c) => c.label ?? c.key);
  const widths = table.columns.map((c, i) => {
    const max = Math.max(
      headers[i].length,
      ...table.rows.map((r) => cellText(r[c.key]).length),
    );
    return Math.min(max, c.maxWidth ?? 60);
  });

  const renderRow = (cells: string[]) =>
    cells
      .map((cell, i) => {
        const truncated = cell.length > widths[i] ? cell.slice(0, widths[i] - 1) + '…' : cell;
        return truncated.padEnd(widths[i]);
      })
      .join('  ')
      .trimEnd();

  const lines = [
    renderRow(headers),
    renderRow(widths.map((w) => '─'.repeat(w))),
    ...table.rows.map((row) => renderRow(table.columns.map((c) => cellText(row[c.key])))),
  ];
  return lines.join('\n');
}

/** True when output should be JSON: explicit --json, or stdout is not a TTY. */
export function wantsJson(jsonFlag: boolean | undefined): boolean {
  return Boolean(jsonFlag) || !process.stdout.isTTY;
}

export function printJson(value: unknown): void {
  process.stdout.write(JSON.stringify(value, null, 2) + '\n');
}

/**
 * Print a result: JSON when requested/piped, a table (or plain line) on a TTY.
 * When `table` is omitted the value prints as JSON regardless.
 */
export function printResult(
  value: unknown,
  opts: { json?: boolean; table?: TableData; text?: string },
): void {
  if (wantsJson(opts.json) || (!opts.table && !opts.text)) {
    printJson(value);
    return;
  }
  process.stdout.write((opts.table ? formatTable(opts.table) : opts.text!) + '\n');
}

/** Errors go to stderr; ApiError/CliError never print a stack trace. */
export function printError(err: unknown): void {
  if (err instanceof ApiError || err instanceof CliError) {
    process.stderr.write(`Error: ${err.message}\n`);
    return;
  }
  process.stderr.write(`Error: ${err instanceof Error ? (err.stack ?? err.message) : String(err)}\n`);
}

import { randomUUID } from 'node:crypto';
import type { PostRecord, PostsPage } from './types.js';

export type ErrorCode =
  | 'VALIDATION'
  | 'UNAUTHORIZED'
  | 'FORBIDDEN'
  | 'NOT_FOUND'
  | 'BILLING'
  | 'PROVIDER_RETIRED'
  | 'THROTTLED'
  | 'CONFLICT'
  | 'SERVER'
  | 'NETWORK'
  | 'UNKNOWN';

export class ApiError extends Error {
  readonly status: number;
  readonly code: ErrorCode;
  /** Raw parsed response body, when it was JSON. */
  readonly body: unknown;

  constructor(status: number, code: ErrorCode, message: string, body?: unknown) {
    super(message);
    this.name = 'ApiError';
    this.status = status;
    this.code = code;
    this.body = body;
  }
}

export interface ClientOptions {
  apiKey: string;
  baseUrl: string;
}

export interface ClientDeps {
  /** Injectable for tests — defaults to a real timer. */
  sleep?: (ms: number) => Promise<void>;
}

export interface RequestOptions {
  query?: Record<string, string | number | boolean | undefined>;
  body?: unknown;
  form?: FormData;
  /** Override the auto-generated Idempotency-Key on mutating requests. */
  idempotencyKey?: string;
}

export interface Client {
  request<T = unknown>(method: string, path: string, options?: RequestOptions): Promise<T>;
  get<T = unknown>(path: string, options?: RequestOptions): Promise<T>;
  post<T = unknown>(path: string, options?: RequestOptions): Promise<T>;
  put<T = unknown>(path: string, options?: RequestOptions): Promise<T>;
  delete<T = unknown>(path: string, options?: RequestOptions): Promise<T>;
}

const API_PREFIX = '/public/v1';
const MUTATING = new Set(['POST', 'PUT', 'DELETE']);
const MAX_429_RETRIES = 1;
const DEFAULT_RETRY_BACKOFF_MS = 1000;

const defaultSleep = (ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms));

function buildUrl(baseUrl: string, path: string, query?: RequestOptions['query']): string {
  const base = baseUrl.replace(/\/+$/, '');
  const url = new URL(`${base}${API_PREFIX}${path}`);
  for (const [key, value] of Object.entries(query ?? {})) {
    if (value === undefined) continue;
    url.searchParams.set(key, String(value));
  }
  return url.toString();
}

/** Pull the most useful human message out of an error response body. */
function serverMessage(body: unknown): string | undefined {
  if (body === null || typeof body !== 'object') return undefined;
  const b = body as Record<string, unknown>;
  for (const key of ['msg', 'message', 'error']) {
    const v = b[key];
    if (typeof v === 'string' && v) return v;
    if (Array.isArray(v) && v.length) return v.map(String).join('; ');
  }
  return undefined;
}

function friendlyError(status: number, body: unknown, retryAfter?: string | null): { code: ErrorCode; message: string } {
  const server = serverMessage(body);
  switch (status) {
    case 400:
      return {
        code: 'VALIDATION',
        message: `Invalid request${server ? `: ${server}` : '. The server rejected the payload.'}`,
      };
    case 401:
      return {
        code: 'UNAUTHORIZED',
        message:
          `Invalid API key${server ? ` (${server})` : ''}. ` +
          'Create a key in the dashboard (Settings → API Keys) or run `postmill login`.',
      };
    case 402:
      return {
        code: 'BILLING',
        message:
          `This action is not available on the current plan${server ? `: ${server}` : ''}. ` +
          'Upgrade in the dashboard under Settings → Billing.',
      };
    case 403:
      return { code: 'FORBIDDEN', message: `Forbidden${server ? `: ${server}` : ''}` };
    case 404:
      return { code: 'NOT_FOUND', message: `Not found${server ? `: ${server}` : ''}` };
    case 409:
      return { code: 'CONFLICT', message: `Conflict${server ? `: ${server}` : ''}` };
    case 410: {
      const b = (body ?? {}) as Record<string, unknown>;
      const latest = typeof b.latestActive === 'string' ? ` Use version "${b.latestActive}" instead.` : '';
      return {
        code: 'PROVIDER_RETIRED',
        message: `The requested provider version has been retired.${latest}${server ? ` (${server})` : ''}`,
      };
    }
    case 429:
      return {
        code: 'THROTTLED',
        message:
          `Rate limit exceeded${retryAfter ? ` — retry after ${retryAfter}s` : ''}. ` +
          'The public API is throttled (600 req/hour; analytics 60/min).',
      };
    default:
      return status >= 500
        ? { code: 'SERVER', message: `Postmill server error (${status})${server ? `: ${server}` : ''}` }
        : { code: 'UNKNOWN', message: `Unexpected response (${status})${server ? `: ${server}` : ''}` };
  }
}

function retryAfterMs(header: string | null, attempt: number): number {
  if (header) {
    const seconds = Number(header);
    if (Number.isFinite(seconds) && seconds >= 0) return seconds * 1000;
    const date = Date.parse(header);
    if (!Number.isNaN(date)) return Math.max(0, date - Date.now());
  }
  return DEFAULT_RETRY_BACKOFF_MS * (attempt + 1);
}

export function createClient(options: ClientOptions, deps: ClientDeps = {}): Client {
  const sleep = deps.sleep ?? defaultSleep;
  const { apiKey, baseUrl } = options;

  async function rawRequest(method: string, path: string, req: RequestOptions): Promise<Response> {
    const headers: Record<string, string> = {
      // Public API keys are sent raw — NO `Bearer` prefix
      // (apps/backend/src/services/auth/public.auth.middleware.ts).
      Authorization: apiKey,
      Accept: 'application/json',
    };
    if (MUTATING.has(method)) {
      headers['Idempotency-Key'] = req.idempotencyKey ?? randomUUID();
    }

    let body: string | FormData | undefined;
    if (req.form) {
      body = req.form; // fetch sets the multipart boundary itself
    } else if (req.body !== undefined) {
      headers['Content-Type'] = 'application/json';
      body = JSON.stringify(req.body);
    }

    let res: Response;
    try {
      res = await fetch(buildUrl(baseUrl, path, req.query), { method, headers, body });
    } catch (err) {
      throw new ApiError(
        0,
        'NETWORK',
        `Could not reach ${baseUrl} (${err instanceof Error ? err.message : String(err)}). ` +
          'Check the base URL and your network connection.',
      );
    }
    return res;
  }

  async function request<T>(method: string, path: string, req: RequestOptions = {}): Promise<T> {
    const verb = method.toUpperCase();

    // Generate the idempotency key once per logical operation so a 429 retry
    // replays under the SAME key instead of looking like a new operation.
    if (MUTATING.has(verb) && !req.idempotencyKey) {
      req = { ...req, idempotencyKey: randomUUID() };
    }

    let res = await rawRequest(verb, path, req);

    // One retry on 429, honoring Retry-After, then give up.
    for (let attempt = 0; res.status === 429 && attempt < MAX_429_RETRIES; attempt++) {
      await sleep(retryAfterMs(res.headers.get('retry-after'), attempt));
      res = await rawRequest(verb, path, req);
    }

    const contentType = res.headers.get('content-type') ?? '';
    const isJson = contentType.includes('application/json');
    const parsed: unknown = isJson
      ? await res.json().catch(() => undefined)
      : await res.text().catch(() => undefined);

    if (!res.ok) {
      const { code, message } = friendlyError(res.status, parsed, res.headers.get('retry-after'));
      throw new ApiError(res.status, code, message, parsed);
    }

    return parsed as T;
  }

  return {
    request,
    get: (path, options) => request('GET', path, options),
    post: (path, options) => request('POST', path, options),
    put: (path, options) => request('PUT', path, options),
    delete: (path, options) => request('DELETE', path, options),
  };
}

/**
 * Cursor pagination helper for GET /posts (`{ posts, cursor }`, page size ≤ 100).
 * Fetches pages until `maxTotal` posts are collected or the cursor runs out.
 */
export async function paginatePosts(
  client: Client,
  query: { startDate: string; endDate: string },
  maxTotal = 100,
  startCursor?: number,
): Promise<{ posts: PostRecord[]; cursor: number | null }> {
  const collected: PostRecord[] = [];
  let cursor: number | null = startCursor ?? null;

  while (collected.length < maxTotal) {
    const limit = Math.min(100, maxTotal - collected.length);
    const page = await client.get<PostsPage>('/posts', {
      query: { ...query, limit, cursor: cursor ?? undefined },
    });
    collected.push(...page.posts);
    cursor = page.cursor;
    if (cursor === null || page.posts.length === 0) break;
  }

  return { posts: collected, cursor };
}

